inline void IMultAx3x4(const T A[12], const T x[4], T Ax[3]) {
  T x0, x1, x2, x3;
  x0 = x[0];
  x1 = x[1];
  x2 = x[2];
  x3 = x[3];
  Ax[0] = A[0] * x0 + A[1] * x1 + A[2] * x2 + A[3] * x3;
  Ax[1] = A[4] * x0 + A[5] * x1 + A[6] * x2 + A[7] * x3;
  Ax[2] = A[8] * x0 + A[9] * x1 + A[10] * x2 + A[11] * x3;

