/** * @brief Compute the distance from a point to the polygon. If the point is * within the polygon, return 0. Otherwise, this distance is * the minimal distance from the point to the edges of the polygon. * @param point The point to compute whose distance to the polygon. * @return The distance from the point to the polygon. */ double DistanceTo(const Vec2d &point) const;
/** * @brief Compute the distance from a line segment to the polygon. * If the line segment is within the polygon, or it has intersect with * the polygon, return 0. Otherwise, this distance is * the minimal distance between the distances from the two ends * of the line segment to the polygon. * @param line_segment The line segment to compute whose distance to * the polygon. * @return The distance from the line segment to the polygon. */ double DistanceTo(const LineSegment2d &line_segment) const;
/** * @brief Compute the distance from a box to the polygon. * If the box is within the polygon, or it has overlap with * the polygon, return 0. Otherwise, this distance is * the minimal distance among the distances from the edges * of the box to the polygon. * @param box The box to compute whose distance to the polygon. * @return The distance from the box to the polygon. */ double DistanceTo(const Box2d &box) const;
/** * @brief Compute the distance from another polygon to the polygon. * If the other polygon is within this polygon, or it has overlap with * this polygon, return 0. Otherwise, this distance is * the minimal distance among the distances from the edges * of the other polygon to this polygon. * @param polygon The polygon to compute whose distance to this polygon. * @return The distance from the other polygon to this polygon. */ double DistanceTo(const Polygon2d &polygon) const;
/** * @brief Compute the square of distance from a point to the polygon. * If the point is within the polygon, return 0. Otherwise, * this square of distance is the minimal square of distance from * the point to the edges of the polygon. * @param point The point to compute whose square of distance to the polygon. * @return The square of distance from the point to the polygon. */ double DistanceSquareTo(const Vec2d &point) const;
/** * @brief Check if a point is within the polygon. * @param point The target point. To check if it is within the polygon. * @return Whether a point is within the polygon or not. */ bool IsPointIn(const Vec2d &point) const;
/** * @brief Check if a point is on the boundary of the polygon. * @param point The target point. To check if it is on the boundary * of the polygon. * @return Whether a point is on the boundary of the polygon or not. */ bool IsPointOnBoundary(const Vec2d &point) const;
/** * @brief Check if the polygon contains a line segment. * @param line_segment The target line segment. To check if the polygon * contains it. * @return Whether the polygon contains the line segment or not. */ bool Contains(const LineSegment2d &line_segment) const;
/** * @brief Check if the polygon contains another polygon. * @param polygon The target polygon. To check if this polygon contains it. * @return Whether this polygon contains another polygon or not. */ bool Contains(const Polygon2d &polygon) const;

