template <typename T>
inline void IMultAB3x4And4x3(const T A[12], const T B[12], T AB[9]) {
  T a, b, c, d;
  a = A[0];
  b = A[1];
  c = A[2];
  d = A[3];
  AB[0] = a * B[0] + b * B[3] + c * B[6] + d * B[9];
  AB[1] = a * B[1] + b * B[4] + c * B[7] + d * B[10];
  AB[2] = a * B[2] + b * B[5] + c * B[8] + d * B[11];

