// 'motorola', 'physical_unit': 'Nm'}
double Scuvcu2313::vcu_torqnegmax(const std::uint8_t* bytes,
                                  int32_t length) const {
  Byte t0(bytes + 4);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 5);
  int32_t t = t1.get_byte(5, 3);
  x <<= 3;
  x |= t;

  double ret = x * 1.500000 + -3000.000000;
  return ret;

