OsqpSpline2dSolver::OsqpSpline2dSolver(const std::vector<double>& t_knots,
                                       const uint32_t order)
    : Spline2dSolver(t_knots, order) {}

void OsqpSpline2dSolver::Reset(const std::vector<double>& t_knots,
                               const uint32_t order) {
  spline_ = Spline2d(t_knots, order);
  kernel_ = Spline2dKernel(t_knots, order);
  constraint_ = Spline2dConstraint(t_knots, order);
}

// customize setup
Spline2dConstraint* OsqpSpline2dSolver::mutable_constraint() {
  return &constraint_;
}

Spline2dKernel* OsqpSpline2dSolver::mutable_kernel() { return &kernel_; }

Spline2d* OsqpSpline2dSolver::mutable_spline() { return &spline_; }

bool OsqpSpline2dSolver::Solve() {
  // Namings here are following osqp convention.
  // For details, visit: https://osqp.org/docs/examples/demo.html

  // change P to csc format
  const MatrixXd& P = kernel_.kernel_matrix();

switch (parking_brake_status(bytes, length)) {
  case 0:
    chassis_detail->mutable_epb()->set_parking_brake_status(Epb::PBRAKE_OFF);
    break;
  case 1:
    chassis_detail->mutable_epb()->set_parking_brake_status(
        Epb::PBRAKE_TRANSITION);
    break;
  case 2:
    chassis_detail->mutable_epb()->set_parking_brake_status(Epb::PBRAKE_ON);
    break;
  case 3:
    chassis_detail->mutable_epb()->set_parking_brake_status(
        Epb::PBRAKE_FAULT);
    break;

max_deceleration_ = vehicle_param_.max_deceleration();

const double mass_fl = control_conf->mpc_controller_conf().mass_fl();
const double mass_fr = control_conf->mpc_controller_conf().mass_fr();
const double mass_rl = control_conf->mpc_controller_conf().mass_rl();
const double mass_rr = control_conf->mpc_controller_conf().mass_rr();
const double mass_front = mass_fl + mass_fr;
const double mass_rear = mass_rl + mass_rr;
mass_ = mass_front + mass_rear;

lf_ = wheelbase_ * (1.0 - mass_front / mass_);
lr_ = wheelbase_ * (1.0 - mass_rear / mass_);
iz_ = lf_ * lf_ * mass_front + lr_ * lr_ * mass_rear;

mpc_eps_ = control_conf->mpc_controller_conf().eps();
mpc_max_iteration_ = control_conf->mpc_controller_conf().max_iteration();

    return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
  }

  return Status::OK();
}

Status SignalsXmlParser::ToPbSubSignalType(const std::string& xml_type,
                                           PbSubSignalType* sub_signal_type) {
  CHECK_NOTNULL(sub_signal_type);

  std::string upper_str = UtilXmlParser::ToUpper(xml_type);

  if (upper_str == "UNKNOWN") {
    *sub_signal_type = hdmap::Subsignal::UNKNOWN;
  } else if (upper_str == "CIRCLE") {
    *sub_signal_type = hdmap::Subsignal::CIRCLE;
  } else if (upper_str == "ARROWLEFT") {
    *sub_signal_type = hdmap::Subsignal::ARROW_LEFT;
  } else if (upper_str == "ARROWFORWARD") {
    *sub_signal_type = hdmap::Subsignal::ARROW_FORWARD;

