                                         int32_t length) const {
  // see table for status code
  Byte frame(bytes + 6);

  uint8_t t = 0;

  t = static_cast<uint8_t>(x & 0xFF);
  Byte to_set0(data + 1);
  to_set0.set_value(t, 0, 8);
  x >>= 8;

  t = x & 0x3;
  Byte to_set1(data + 0);
  to_set1.set_value(t, 0, 2);
}

