inline void IInvert2x2(const float A[4], float Ai[4]) {
  float d = IDeterminant2x2(A);
  float sf = IRec(d);
  Ai[0] = sf * (A[3]);
  Ai[1] = sf * (-A[1]);
  Ai[2] = sf * (-A[2]);
  Ai[3] = sf * (A[0]);
}

inline void IInvert2x2(const int A[4], double Ai[4]) {
  int d = IDeterminant2x2(A);
  double sf = IRec(d);
  Ai[0] = sf * (A[3]);
  Ai[1] = sf * (-A[1]);
  Ai[2] = sf * (-A[2]);
  Ai[3] = sf * (A[0]);
}

