void Throttle62::UpdateData(uint8_t *data) {
  set_pedal_p(data, pedal_cmd_);
  set_enable_p(data, pedal_enable_);
  set_clear_driver_override_flag_p(data, clear_driver_override_flag_);
  set_ignore_driver_override_p(data, ignore_driver_override_);
  set_watchdog_counter_p(data, watchdog_counter_);
}

void Throttle62::Reset() {
  pedal_cmd_ = 0.0;
  pedal_enable_ = false;
  clear_driver_override_flag_ = false;
  ignore_driver_override_ = false;

object_ptr->polygon[1].x = x1 * cos_theta + y2 * sin_theta +
    object_ptr->center[0];
object_ptr->polygon[1].y = y2 * cos_theta - x1 * sin_theta +
    object_ptr->center[1];
object_ptr->polygon[1].z = 0.0;

object_ptr->polygon[2].x = x2 * cos_theta + y2 * sin_theta +
    object_ptr->center[0];
object_ptr->polygon[2].y = y2 * cos_theta - x2 * sin_theta +
    object_ptr->center[1];
object_ptr->polygon[2].z = 0.0;

object_ptr->polygon[3].x = x2 * cos_theta + y1 * sin_theta +
    object_ptr->center[0];
object_ptr->polygon[3].y = y1 * cos_theta - x2 * sin_theta +
    object_ptr->center[1];
object_ptr->polygon[3].z = 0.0;

  distance += IHammingLut(x[0], y[0]);
  distance += IHammingLut(x[1], y[1]);
  distance += IHammingLut(x[2], y[2]);
  distance += IHammingLut(x[3], y[3]);
  return distance;
}
