  unsigned int distance = 0;
  distance += IHammingLut(x[0], y[0]);
  distance += IHammingLut(x[1], y[1]);
  distance += IHammingLut(x[2], y[2]);
  distance += IHammingLut(x[3], y[3]);
  distance += IHammingLut(x[4], y[4]);
  distance += IHammingLut(x[5], y[5]);
  distance += IHammingLut(x[6], y[6]);
  distance += IHammingLut(x[7], y[7]);

  dist[1] = plane[1] != nullptr
                ? IPlaneToPointSignedDistanceWUnitNorm(plane[1], cptr)
                : FLT_MAX;
  dist[2] = plane[2] != nullptr
                ? IPlaneToPointSignedDistanceWUnitNorm(plane[2], cptr)
                : FLT_MAX;
  dist[3] = plane[3] != nullptr
                ? IPlaneToPointSignedDistanceWUnitNorm(plane[3], cptr)
                : FLT_MAX;
  for (i = 1; i < 4; ++i) {
    if (min_abs_dist > IAbs(dist[i])) {
      min_abs_dist = IAbs(dist[i]);
      id = i;
    }
  }
}
height_above_ground[pos] = dist[id];
++iter;

  return value;
}

int32_t Version7f::minor_version(const std::uint8_t *bytes,
                                 int32_t length) const {
  Byte frame_high(bytes + 5);
  int32_t high = frame_high.get_byte(0, 8);
  Byte frame_low(bytes + 4);
  int32_t low = frame_low.get_byte(0, 8);
  int32_t value = (high << 8) | low;
  return value;
}

int32_t Version7f::build_number(const std::uint8_t *bytes,
                                int32_t length) const {
  Byte frame_high(bytes + 7);
  int32_t high = frame_high.get_byte(0, 8);
  Byte frame_low(bytes + 6);
  int32_t low = frame_low.get_byte(0, 8);
  int32_t value = (high << 8) | low;
  return value;

double Wheelspeed6a::front_right_wheel_speed(const std::uint8_t *bytes,
                                             int32_t length) const {
  DCHECK_GE(length, 4);
  return parse_two_frames(bytes[2], bytes[3]);
}

double Wheelspeed6a::rear_left_wheel_speed(const std::uint8_t *bytes,
                                           int32_t length) const {
  DCHECK_GE(length, 6);
  return parse_two_frames(bytes[4], bytes[5]);
}

double Wheelspeed6a::rear_right_wheel_speed(const std::uint8_t *bytes,
                                            int32_t length) const {
  DCHECK_GE(length, 8);
  return parse_two_frames(bytes[6], bytes[7]);
}

double Wheelspeed6a::parse_two_frames(const std::uint8_t low_byte,
                                      const std::uint8_t high_byte) const {
  Byte high_frame(&high_byte);
  int32_t high = high_frame.get_byte(0, 8);
  Byte low_frame(&low_byte);
  int32_t low = low_frame.get_byte(0, 8);
  int32_t value = (high << 8) | low;

