double Spline2d::SecondDerivativeY(const double t) const {
  if (splines_.size() == 0) {
    return 0.0;
  }
  uint32_t index = find_index(t);
  return splines_[index].SecondDerivativeY(t - t_knots_[index]);
}

double Spline2d::ThirdDerivativeX(const double t) const {
  if (splines_.size() == 0) {
