template <class T>
T* DisjointSetFind(T* x) {
  T* y = x->parent;
  if (y == x || y->parent == y) {
    return y;
  }
  T* root = DisjointSetFindLoop(y->parent);
  x->parent = root;
  y->parent = root;
  return root;
}

template <class T>
void DisjointSetMerge(T* x, const T* y) {}

template <class T>
void DisjointSetUnion(T* x, T* y) {
  x = DisjointSetFind(x);
  y = DisjointSetFind(y);
  if (x == y) {
    return;
  }
  if (x->node_rank < y->node_rank) {
    x->parent = y;

  return right_out_sorted_range_;
}

