  t = static_cast<uint8_t>(x & 0x3);
  Byte to_set0(data + 2);
  to_set0.set_value(t, 6, 2);
  x >>= 2;

  t = static_cast<uint8_t>(x & 0xFF);
  Byte to_set1(data + 3);
  to_set1.set_value(t, 0, 8);
  x >>= 8;

  t = static_cast<uint8_t>(x & 0x3);
  Byte to_set2(data + 4);
  to_set2.set_value(t, 0, 2);

