bool DataProvider::to_rgb_image() {
  if (!rgb_ready_) {
    NppiSize roi;
    roi.height = src_height_;
    roi.width = src_width_;
    if (bgr_ready_) {
      // BGR2RGB takes less than 0.010ms on K2200
      const int order[] = {2, 1, 0};
      nppiSwapChannels_8u_C3R(bgr_->gpu_data(),
                              bgr_->width_step(),
                              rgb_->mutable_gpu_data(),
                              rgb_->width_step(),
                              roi, order);
      rgb_ready_ = true;
    } else if (gray_ready_) {
      nppiDup_8u_C1C3R(gray_->gpu_data(),
                       gray_->width_step(),
                       rgb_->mutable_gpu_data(),
                       rgb_->width_step(),
                       roi);
      rgb_ready_ = true;
    } else {
      AWARN << "No image data filled yet, return uninitialized blob!";
      return false;
    }
  }
  return true;

