int ijk0 = static_cast<int>(
    floor(input_->points[cp].x * inverse_leaf_size_[0]) -
    static_cast<float>(min_b_[0]));
int ijk1 = static_cast<int>(
    floor(input_->points[cp].y * inverse_leaf_size_[1]) -
    static_cast<float>(min_b_[1]));
int ijk2 = static_cast<int>(
    floor(input_->points[cp].z * inverse_leaf_size_[2]) -
    static_cast<float>(min_b_[2]));
// Compute the centroid leaf index
int idx =
    ijk0 * divb_mul_[0] + ijk1 * divb_mul_[1] + ijk2 * divb_mul_[2];

Leaf& leaf = leaves_[idx];
if (leaf.nr_points_ == 0) {
  leaf.centroid.resize(centroid_size);
  leaf.centroid.setZero();
}

//! added by wangcheng
leaf.cloud_.points.push_back(input_->points[cp]);

Eigen::Vector3d pt3d(input_->points[cp].x, input_->points[cp].y,
                     input_->points[cp].z);
// Accumulate point sum for centroid calculation
leaf.mean_ += pt3d;
// Accumulate x*xT for single pass covariance calculation
leaf.cov_ += pt3d * pt3d.transpose();

// Do we need to process all the fields?
if (!downsample_all_data_) {
  Eigen::Vector4f pt(input_->points[cp].x, input_->points[cp].y,
                     input_->points[cp].z, 0);
  leaf.centroid.template head<4>() += pt;
} else {
  // Copy all the fields
  Eigen::VectorXf centroid = Eigen::VectorXf::Zero(centroid_size);
  pcl::for_each_type<FieldList>(pcl::NdCopyPointEigenFunctor<PointT>(
      input_->points[cp], centroid));
  // ---[ RGB special case
  if (rgba_index >= 0) {
    // Fill r/g/b data, assuming that the order is BGRA
    const pcl::RGB& rgb = *reinterpret_cast<const pcl::RGB*>(
        reinterpret_cast<const char*>(&input_->points[cp]) +
        rgba_index);
    centroid[centroid_size - 4] = rgb.a;
    centroid[centroid_size - 3] = rgb.r;
    centroid[centroid_size - 2] = rgb.g;
    centroid[centroid_size - 1] = rgb.b;
  }
  leaf.centroid += centroid;
}
++leaf.nr_points_;

    right_road_sample->set_width(right_width);

    sub_node = sub_node->NextSiblingElement("sampleAssociation");
  }

  return Status::OK();
}

Status LanesXmlParser::ParseObjectOverlapGroup(
    const tinyxml2::XMLElement& xml_node,
    std::vector<OverlapWithLane>* object_overlaps) {
  CHECK_NOTNULL(object_overlaps);

  auto object_overlap = xml_node.FirstChildElement("objectOverlapGroup");
  if (object_overlap) {
    auto sub_node = object_overlap->FirstChildElement("objectReference");
    while (sub_node) {
      std::string object_id;
      double start_s = 0.0;
      double end_s = 0.0;
      int checker =
          UtilXmlParser::QueryStringAttribute(*sub_node, "id", &object_id);
      checker += sub_node->QueryDoubleAttribute("startOffset", &start_s);
      checker += sub_node->QueryDoubleAttribute("endOffset", &end_s);
      if (checker != tinyxml2::XML_SUCCESS) {
        std::string err_msg = "Error parse lane object overlap";
        return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
      }

      bool is_merge = false;
      checker = sub_node->QueryBoolAttribute("isMerge", &is_merge);
      if (checker != tinyxml2::XML_SUCCESS) {
        is_merge = false;
      }

      OverlapWithLane overlap_with_lane;
      overlap_with_lane.object_id = object_id;
      overlap_with_lane.start_s = start_s;
      overlap_with_lane.end_s = end_s;
      overlap_with_lane.is_merge = is_merge;

