// @brief: compute the distance between velodyne64 observation and
// velodyne64 observation
// @return the distance of velodyne64 vs. velodyne64
float TrackObjectDistance::ComputeLidarLidar(
    const SensorObjectConstPtr& fused_object,
    const SensorObjectPtr& sensor_object, const Eigen::Vector3d& ref_pos,
    int range) {
  double center_distance = (sensor_object->GetBaseObject()->center -
                            fused_object->GetBaseObject()->center)
                               .head(2)
                               .norm();
  if (center_distance > s_lidar2lidar_association_center_dist_threshold_) {
    ADEBUG << "center distance exceed lidar2lidar tight threshold: "
           << "center_dist@" << center_distance << ", "
           << "tight_threh@"
           << s_lidar2lidar_association_center_dist_threshold_;
    return (std::numeric_limits<float>::max)();
  }
  float distance =
      ComputePolygonDistance3d(fused_object, sensor_object, ref_pos, range);
  ADEBUG << "ComputeLidarLidar distance: " << distance;
  return distance;
}

// @brief: compute the distance between velodyne64 observation and
// radar observation
// @return distance of velodyne64 vs. radar
float TrackObjectDistance::ComputeLidarRadar(
    const SensorObjectConstPtr& fused_object,
    const SensorObjectPtr& sensor_object, const Eigen::Vector3d& ref_pos,
    int range) {
  double center_distance = (sensor_object->GetBaseObject()->center -
                            fused_object->GetBaseObject()->center)
                               .head(2)
                               .norm();
  if (center_distance > s_lidar2radar_association_center_dist_threshold_) {
    ADEBUG << "center distance exceed lidar2radar tight threshold: "
           << "center_dist@" << center_distance << ", "
           << "tight_threh@"
           << s_lidar2radar_association_center_dist_threshold_;
    return (std::numeric_limits<float>::max)();
  }
  float distance =
      ComputePolygonDistance3d(fused_object, sensor_object, ref_pos, range);
  ADEBUG << "ComputeLidarRadar distance: " << distance;
  return distance;

  return Status::OK();
}

Status LanesXmlParser::ParseRoadSampleAssociates(
    const tinyxml2::XMLElement& xml_node, PbLane* lane) {
  CHECK_NOTNULL(lane);
  auto sub_node = xml_node.FirstChildElement("roadSampleAssociations");
  if (sub_node == nullptr) {
    std::string err_msg = "Error parse road sample associations";
    return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
  }
  sub_node = sub_node->FirstChildElement("sampleAssociation");
  if (sub_node == nullptr) {
    std::string err_msg = "Error parse road sample association";
    return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
  }

  while (sub_node) {
    double left_width = 0.0;
    double right_width = 0.0;
    double s = 0.0;
    int checker = sub_node->QueryDoubleAttribute("sOffset", &s);
    checker += sub_node->QueryDoubleAttribute("leftWidth", &left_width);
    checker += sub_node->QueryDoubleAttribute("rightWidth", &right_width);
    if (checker != tinyxml2::XML_SUCCESS) {
      std::string err_msg = "Error parse road sample association attribute";
      return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
    }

    auto left_road_sample = lane->add_left_road_sample();
    left_road_sample->set_s(s);
    left_road_sample->set_width(left_width);

    auto right_road_sample = lane->add_right_road_sample();
    right_road_sample->set_s(s);
    right_road_sample->set_width(right_width);

    sub_node = sub_node->NextSiblingElement("sampleAssociation");
  }

  return Status::OK();

