void Ge3Controller::SecurityDogThreadFunc() {
  int32_t vertical_ctrl_fail = 0;
  int32_t horizontal_ctrl_fail = 0;

  if (can_sender_ == nullptr) {
    AERROR << "Fail to run SecurityDogThreadFunc() because can_sender_ is "
              "nullptr.";
    return;
  }
  while (!can_sender_->IsRunning()) {
    std::this_thread::yield();
  }

  std::chrono::duration<double, std::micro> default_period{50000};
  int64_t start = 0;
  int64_t end = 0;
  while (can_sender_->IsRunning()) {
    start = ::apollo::common::time::AsInt64<::apollo::common::time::micros>(
        ::apollo::common::time::Clock::Now());
    const Chassis::DrivingMode mode = driving_mode();
    bool emergency_mode = false;

    // 1. horizontal control check
    if ((mode == Chassis::COMPLETE_AUTO_DRIVE ||
         mode == Chassis::AUTO_STEER_ONLY) &&
        CheckResponse(CHECK_RESPONSE_STEER_UNIT_FLAG, false) == false) {
      ++horizontal_ctrl_fail;
      if (horizontal_ctrl_fail >= kMaxFailAttempt) {
        emergency_mode = true;
        set_chassis_error_code(Chassis::MANUAL_INTERVENTION);
      }
    } else {
      horizontal_ctrl_fail = 0;
    }

    // 2. vertical control check
    if ((mode == Chassis::COMPLETE_AUTO_DRIVE ||
         mode == Chassis::AUTO_SPEED_ONLY) &&
        CheckResponse(CHECK_RESPONSE_SPEED_UNIT_FLAG, false) == false) {
      ++vertical_ctrl_fail;
      if (vertical_ctrl_fail >= kMaxFailAttempt) {
        emergency_mode = true;
        set_chassis_error_code(Chassis::MANUAL_INTERVENTION);
      }
    } else {
      vertical_ctrl_fail = 0;
    }
    if (CheckChassisError()) {
      set_chassis_error_code(Chassis::CHASSIS_ERROR);
      emergency_mode = true;
    }

    if (emergency_mode && mode != Chassis::EMERGENCY_MODE) {
      set_driving_mode(Chassis::EMERGENCY_MODE);
      message_manager_->ResetSendMessages();
    }
    end = ::apollo::common::time::AsInt64<::apollo::common::time::micros>(
        ::apollo::common::time::Clock::Now());
    std::chrono::duration<double, std::micro> elapsed{end - start};
    if (elapsed < default_period) {
      std::this_thread::sleep_for(default_period - elapsed);
    } else {
      AERROR << "Too much time consumption in Ge3Controller looping process:"
             << elapsed.count();
    }
  }
}

bool Ge3Controller::CheckResponse(const int32_t flags, bool need_wait) {

for (const auto &id : ids.crosswalk()) {
  map_id.set_id(id);
  auto element = SimMap()->GetCrosswalkById(map_id);
  if (element) {
    *result.add_crosswalk() = element->crosswalk();
  }
}

for (const auto &id : ids.junction()) {
  map_id.set_id(id);
  auto element = SimMap()->GetJunctionById(map_id);
  if (element) {
    *result.add_junction() = element->junction();
  }
}

for (const auto &id : ids.signal()) {
  map_id.set_id(id);
  auto element = SimMap()->GetSignalById(map_id);
  if (element) {
    *result.add_signal() = element->signal();
  }
}

for (const auto &id : ids.stop_sign()) {
  map_id.set_id(id);
  auto element = SimMap()->GetStopSignById(map_id);
  if (element) {
    *result.add_stop_sign() = element->stop_sign();
  }
}

for (const auto &id : ids.yield()) {
  map_id.set_id(id);
  auto element = SimMap()->GetYieldSignById(map_id);
  if (element) {
    *result.add_yield() = element->yield_sign();
  }
