void GnssMagTransfer::Transfer(
    const apollo::drivers::gnss::GlonassOrbit &in,
    GlonassOrbitMsg* out) {
  CHECK_NOTNULL(out);
  if (in.has_gnss_type()) {
    out->set_gnss_type(GnssType(in.gnss_type()));
  }
  if (in.has_slot_prn()) {
    out->set_slot_prn(in.slot_prn());
  }
  if (in.has_gnss_time_type()) {
    out->set_gnss_time_type(GnssTimeType(in.gnss_time_type()));
  }
  if (in.has_toe()) {
    out->set_toe(in.toe());
  }
  if (in.has_year()) {
    out->set_year(in.year());
  }
  if (in.has_month()) {
    out->set_month(in.month());
  }
  if (in.has_day()) {
    out->set_day(in.day());
  }
  if (in.has_hour()) {
    out->set_hour(in.hour());
  }
  if (in.has_minute()) {
    out->set_minute(in.minute());
  }
  if (in.has_second_s()) {
    out->set_second_s(in.second_s());
  }
  if (in.has_frequency_no()) {
    out->set_frequency_no(in.frequency_no());
  }
  if (in.has_week_num()) {
    out->set_week_num(in.week_num());
  }
  if (in.has_week_second_s()) {
    out->set_week_second_s(in.week_second_s());
  }
  if (in.has_tk()) {
    out->set_tk(in.tk());
  }
  if (in.has_clock_offset()) {
    out->set_clock_offset(in.clock_offset());
  }
  if (in.has_clock_drift()) {
    out->set_clock_drift(in.clock_drift());
  }
  if (in.has_health()) {
    out->set_health(in.health());
  }
  if (in.has_position_x()) {
    out->set_position_x(in.position_x());
  }
  if (in.has_position_y()) {
    out->set_position_y(in.position_y());
  }
  if (in.has_position_z()) {
    out->set_position_z(in.position_z());
  }
  if (in.has_velocity_x()) {
    out->set_velocity_x(in.velocity_x());
  }
  if (in.has_velocity_y()) {
    out->set_velocity_y(in.velocity_y());
  }
  if (in.has_velocity_z()) {
    out->set_velocity_z(in.velocity_z());
  }
  if (in.has_accelerate_x()) {
    out->set_accelerate_x(in.accelerate_x());
  }
  if (in.has_accelerate_y()) {
    out->set_accelerate_y(in.accelerate_y());
  }
  if (in.has_accelerate_z()) {
    out->set_accelerate_z(in.accelerate_z());
  }
  if (in.has_infor_age()) {
    out->set_infor_age(in.infor_age());

std::vector<SpeedPoint> SpeedProfileGenerator::GenerateInitSpeedProfile(
    const TrajectoryPoint& planning_init_point,
    const ReferenceLineInfo* reference_line_info) {
  std::vector<SpeedPoint> speed_profile;
  const auto* last_frame = FrameHistory::Instance()->Latest();
  if (!last_frame) {
    AWARN << "last frame is empty";
    return speed_profile;
  }
  const ReferenceLineInfo* last_reference_line_info =
      last_frame->DriveReferenceLineInfo();
  if (!last_reference_line_info) {
    ADEBUG << "last reference line info is empty";
    return speed_profile;
  }
  if (!reference_line_info->IsStartFrom(*last_reference_line_info)) {
    ADEBUG << "Current reference line is not started previous drived line";
    return speed_profile;
  }
  const auto& last_speed_data = last_reference_line_info->speed_data();

  if (!last_speed_data.empty()) {
    const auto& last_init_point = last_frame->PlanningStartPoint().path_point();
    Vec2d last_xy_point(last_init_point.x(), last_init_point.y());
    SLPoint last_sl_point;
    if (!last_reference_line_info->reference_line().XYToSL(last_xy_point,
                                                           &last_sl_point)) {
      AERROR << "Fail to transfer xy to sl when init speed profile";
    }

    Vec2d xy_point(planning_init_point.path_point().x(),
                   planning_init_point.path_point().y());
    SLPoint sl_point;
    if (!last_reference_line_info->reference_line().XYToSL(xy_point,
                                                           &sl_point)) {
      AERROR << "Fail to transfer xy to sl when init speed profile";
    }

    double s_diff = sl_point.s() - last_sl_point.s();
    double start_time = 0.0;
    double start_s = 0.0;
    bool is_updated_start = false;
    for (const auto& speed_point : last_speed_data) {
      if (speed_point.s() < s_diff) {
        continue;
      }
      if (!is_updated_start) {
        start_time = speed_point.t();
        start_s = speed_point.s();
        is_updated_start = true;
      }
      SpeedPoint refined_speed_point;
      refined_speed_point.set_s(speed_point.s() - start_s);
      refined_speed_point.set_t(speed_point.t() - start_time);
      refined_speed_point.set_v(speed_point.v());
      refined_speed_point.set_a(speed_point.a());
      refined_speed_point.set_da(speed_point.da());
      speed_profile.push_back(std::move(refined_speed_point));
    }
  }
  return speed_profile;
}

// a dummy simple hot start
// TODO(All): refine the hotstart speed profile
std::vector<SpeedPoint> SpeedProfileGenerator::GenerateSpeedHotStart(
    const TrajectoryPoint& planning_init_point) {
  std::vector<SpeedPoint> hot_start_speed_profile;
  double s = 0.0;
  double t = 0.0;
  double v = common::math::Clamp(planning_init_point.v(), 5.0,
                                 FLAGS_planning_upper_speed_limit);
  while (t < FLAGS_trajectory_time_length) {
    SpeedPoint speed_point;
    speed_point.set_s(s);
    speed_point.set_t(t);
    speed_point.set_v(v);

    hot_start_speed_profile.push_back(std::move(speed_point));

    t += FLAGS_trajectory_time_min_interval;
    s += v * FLAGS_trajectory_time_min_interval;
  }
  return hot_start_speed_profile;

  uint16_t freqo;      // frequency channel offset for satellite
                       // in the range 0 to 20
  uint8_t sat_type;    // Satellite type where(0=GLO_SAT, 1=GLO_SAT_M,
                       // 2=GLO_SAT_K)
  uint8_t reserved_1;  // Reserved
  uint16_t e_week;     // reference week of ephemeris(GPS reference time)
  uint32_t e_time;     // reference time of ephemeris(GPS reference time) in ms
  uint32_t t_offset;   // integer seconds between GPS and GLONASS time.
                       // A positive value implies GLONASS is ahead
                       // of GPS reference time.
  uint16_t Nt;  // Calendar number of day within 4 year interval starting at
                // Jan 1 of leap year
  uint8_t reserved_2;  // Reserved
  uint8_t reserved_3;  // Reserved
  uint32_t issue;      // 15 minute interval number corresponding to ephemeris
                       // reference time
  uint32_t health;     // Ephemeris health where 0-3=GOOD, 4-15=BAD
  double pos_x;  // X coordinate for satellite at reference time (PZ-90.02),
                 // in meters
  double pos_y;  // Y coordinate for satellite at reference time (PZ-90.02),
                 // in meters
  double pos_z;  // Z coordinate for satellite at reference time (PZ-90.02),
                 // in meters
  double vel_x;  // X coordinate for satellite velocity at reference
                 // time(PZ-90.02), in meters/s
  double vel_y;  // Y coordinate for satellite velocity at reference
                 // time(PZ-90.02), in meters/s
  double vel_z;  // Z coordinate for satellite velocity at reference
                 // time(PZ-90.02), in meters/s
  double acc_x;  // X coordinate for lunisolar acceleration at reference
                 // time(PZ-90.02), in meters/s/s
  double acc_y;  // Y coordinate for lunisolar acceleration at reference
                 // time(PZ-90.02), in meters/s/s
  double acc_z;  // Z coordinate for lunisolar acceleration at reference
                 // time(PZ-90.02), in meters/s/s
  double tau_n;  // Correction to the nth satellite time t_n relative to
                 // GLONASS time_t, in seconds
  double delta_tau_n;  // Time difference between navigation RF signal
                       // transmitted in L2 sub-band and
                       // navigation RF signal transmitted in
                       // L1 sub-band by nth satellite , in seconds
  double gamma;        // frequency correction , in seconds/second
  uint32_t Tk;   // Time of frame start(since start of GLONASS day), in seconds
  uint32_t P;    // technological parameter
  uint32_t Ft;   // User range
  uint32_t age;  // age of data, in days
  uint32_t Flags;  // information flags
};
static_assert(sizeof(GLO_Ephemeris) == 144, "Incorrect size of GLO_Ephemeris.");

struct GPS_Ephemeris {
  uint32_t prn;      // Satellite prn number
  double tow;        // Time stamp of subframe 0
  uint32_t health;   // Health status -a 6-bit health code as defined in
                     // ICD-GPS-200
  uint32_t iode1;    // issue of ephemeris data 1
  uint32_t iode2;    // issue of ephemeris data 2
  uint32_t week;     // GPS reference week number
  uint32_t z_week;   // Z count week number
  double toe;        // reference time for ephemeris, seconds
  double A;          // semi-major axis, metres
  double delta_A;    // Mean motion difference, radians/second
  double M_0;        // Mean anomaly of reference time, radians
  double ecc;        // Eccentricity. dimensionless-quantity defined for
                     // a conic section where e=0 is a circle, e=1 is a parabola
                     // 0<e<1 os an ellipse and e>1 is a hyperbola
  double omega;      // Argument of perigee, radians -measurement along the
                     // orbital path from the ascending node to the point where
                     // the SV os closest to the earth, in the direction of
                     // the SV's motion
  double cuc;        // Argument of latitude
  double cus;        // Argument of latitude
  double crc;        // Orbit radius
  double crs;        // Orbit radius
  double cic;        // Inclination
  double cis;        // Inclination
  double I_0;        // Inclination angle at reference time, radians
  double dot_I;      // Rate of inclination angle, radians/second
  double omega_0;    // right ascension, radians
  double dot_omega;  // rate of right ascension, radians/second
  uint32_t iodc;     // issue of data clock
  double toc;        // SV clock correction term, seconds
  double tgd;        // Estimated group delay difference seconds
  double af0;        // Clock aging parameter. seconds
  double af1;        // Clock aging parameter
  double af2;        // Clock aging parameter

  chassis->mutable_lexus()
      ->mutable_dash_controls_left_rpt_20c()
      ->set_command_output_fault(command_output_fault(bytes, length));
}

