double ClusterGeneralInfo701::longitude_dist(const std::uint8_t* bytes,
                                             int32_t length) const {
  Byte t0(bytes + 1);
  uint32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 2);
  uint32_t t = t1.get_byte(3, 5);
  x <<= 5;
  x |= t;
  double ret = x * CLUSTER_DIST_RES + CLUSTER_DIST_LONG_MIN;
  return ret;
}

